function solve(n, edges) {
  // Kruskal: gunakan union-find untuk mendeteksi siklus.
  const induk = Array.from({ length: n }, (_, i) => i)
  const cari = (x) => (induk[x] === x ? x : (induk[x] = cari(induk[x])))

  let total = 0
  // Coba sisi dari yang paling ringan.
  for (const [u, v, w] of [...edges].sort((p, q) => p[2] - q[2])) {
    const a = cari(u)
    const b = cari(v)
    if (a !== b) {
      induk[a] = b // gabungkan dua komponen
      total += w
    }
  }
  return total
}
